details:
It seems that if you change the value and call RequestSerialization inside OnPlayerJoined, it will not synchronize.

At least, I observed it as the master.

```

// normal synced behaviour

[UdonBehaviourSyncMode(BehaviourSyncMode.Manual)]

public class ForceRoomPermissionAllowToPlayer : UdonSharpBehaviour

{

    public override void OnPlayerJoined(VRCPlayerApi player)

    {

        if (player.isLocal)

        {

            _ApplyToMe();

            // SendCustomEventDelayedSeconds(nameof(_ApplyToMe), 1f);

        }

    }

    public void _ApplyToMe()

    {

        if (!allow) return;

        var permission = (RoomPermissionByPlayer)Networking.FindComponentInPlayerObjects(Networking.LocalPlayer, template);

        permission._SetAllowed(true);

    }

}

// a child of the player object

[UdonBehaviourSyncMode(BehaviourSyncMode.Manual)]

public class RoomPermissionByPlayer : UdonSharpBehaviour

{

    // THIS VALUE IS NOT SYNCED IN THE MASTER CLIENT!

    [UdonSynced, FieldChangeCallback(nameof(isAllowed))] bool _isAllowed = false;

    public bool isAllowed

    {

        get => _isAllowed;

        set

        {

            _isAllowed = value;

            Apply();

        }

    }

    [PublicAPI]

    [NetworkCallable(3)]

    public void _SetAllowed(bool allowed)

    {

        if (Networking.IsOwner(gameObject))

        {

            isAllowed = allowed;

            RequestSerialization();

        }

        else

        {

            SendCustomNetworkEvent(VRC.Udon.Common.Interfaces.NetworkEventTarget.Owner, nameof(_SetAllowed), allowed);

        }

    }

}

```

When I delayed this by one second using `SendCustomEventDelayedSeconds`, it started working normally.

Even if the initial synchronization fails, changing the value at a later timing will still synchronize it.

Anyway, it seems that only the changes made at the timing of OnPlayerJoined are not being reflected.
